package vn.rtr.aeris.shell29;
import java.nio.file.*;import java.nio.channels.FileChannel;import java.nio.ByteBuffer;import java.io.*;import java.util.*;
/** Opaque immutable historical snapshots; no authority/player restoration API. */
public final class HistoryStore {
 public static final int MAX_BYTES=262144,MAX_FILES=32;public static final long TOTAL_BYTES=2097152,RESERVE_BYTES=16777216;private final Path root;
 public HistoryStore(Path root)throws IOException{this.root=root;Files.createDirectories(root);if(Files.isSymbolicLink(root))throw new IOException("History root symlink");}
 private void bounds(int bytes)throws IOException{long count=0,total=0;try(DirectoryStream<Path> ds=Files.newDirectoryStream(root,"*.json")){for(Path p:ds){count++;total+=Files.size(p);}}if(count>=MAX_FILES||total+bytes>TOTAL_BYTES||Files.getFileStore(root).getUsableSpace()<RESERVE_BYTES+bytes)throw new IOException("History quota/reserve; no automatic deletion");}
 public synchronized String save(byte[] bytes)throws IOException{if(bytes==null||bytes.length==0||bytes.length>MAX_BYTES)throw new IOException("Snapshot size");String hash=Plan.hash(bytes);Path dst=root.resolve(hash+".json");if(Files.exists(dst)){if(!Arrays.equals(read(hash),bytes))throw new IOException("Digest collision");return hash;}bounds(bytes.length);Path pending=root.resolve(hash+".pending");boolean created=false;try{try(FileChannel out=FileChannel.open(pending,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){created=true;ByteBuffer buffer=ByteBuffer.wrap(bytes);while(buffer.hasRemaining())out.write(buffer);out.force(true);}Files.move(pending,dst);return hash;}finally{if(created)Files.deleteIfExists(pending);}}
 public synchronized byte[] read(String hash)throws IOException{if(hash==null||!hash.matches("[a-f0-9]{64}"))throw new IOException("History reference");Path p=root.resolve(hash+".json");if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||Files.size(p)>MAX_BYTES)throw new IOException("History path/size");byte[] b=Files.readAllBytes(p);if(!hash.equals(Plan.hash(b)))throw new IOException("History SHA mismatch; retain evidence");return b;}
 public synchronized List<String> list()throws IOException{ArrayList<String> r=new ArrayList<>();try(DirectoryStream<Path> ds=Files.newDirectoryStream(root,"*.json")){for(Path p:ds){if(r.size()>=MAX_FILES)throw new IOException("History index bound");String n=p.getFileName().toString();if(!n.matches("[a-f0-9]{64}\\.json"))throw new IOException("History name");r.add(n.substring(0,64));}}Collections.sort(r);return r;}
}
